        raise ValueError(f'Invalid duration: {s!r}')

    match = _DURATION_RE.fullmatch(s.strip())
    if match is None or not any(match.groups()):
        raise ValueError(f'Invalid duration: {s!r}')

    return sum(
        int(amount) * multiplier
        for amount, multiplier in zip(match.groups(), _MULTIPLIERS)
